INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(400, 'column', '/ˈkɒləm/', 'noun', '{"zh-TW":["欄；柱"],"en":["a vertical division of a page","a pillar supporting a structure"]}', '{"root":{"text":"column","meaning":"pillar (柱子)"},"logic":"源自拉丁語 columna（柱子），引申為報紙或表格的直行。"}', 'newspaper column / column chart / support column', '[{"en":"The data is organized in three columns.","zh-TW":"數據以三欄組織排列。"},{"en":"She writes a weekly column for the newspaper.","zh-TW":"她為報紙寫每週專欄。"}]', '{"noun":"columnist"}', NULL, 2, 400),
(401, 'combination', '/ˌkɒmbɪˈneɪʃn/', 'noun', '{"zh-TW":["組合；結合"],"en":["a joining of different things"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"bin","meaning":"two (二)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"把兩個以上的東西放在一起的過程，即「組合」。"}', 'a combination of / winning combination', '[{"en":"The dish uses a combination of herbs and spices.","zh-TW":"這道菜使用了多種香草和香料的組合。"},{"en":"Success requires a combination of talent and hard work.","zh-TW":"成功需要天賦和努力的結合。"}]', '{"verb":"combine"}', NULL, 4, 401),
(402, 'come', '/kʌm/', 'verb', '{"zh-TW":["來；到來"],"en":["to move toward","to arrive"]}', NULL, 'come up with / come across', '[{"en":"She came up with a brilliant idea.","zh-TW":"她想出了一個絕妙的點子。"},{"en":"Please come to my office at noon.","zh-TW":"請中午到我的辦公室來。"}]', '{"verb":"come","noun":"outcome","adjective":"incoming"}', NULL, 1, 402),
(403, 'comedy', '/ˈkɒmədi/', 'noun', '{"zh-TW":["喜劇"],"en":["entertainment that makes people laugh"]}', NULL, 'romantic comedy / comedy show', '[{"en":"I prefer comedies to horror films.","zh-TW":"比起恐怖片我更喜歡喜劇。"},{"en":"The comedy show was hilarious.","zh-TW":"那場喜劇表演太好笑了。"}]', '{"noun2":"comedian"}', NULL, 2, 403),
(404, 'comfort', '/ˈkʌmfərt/', 'noun', '{"zh-TW":["舒適；安慰"],"en":["a state of ease; something that gives relief","a state of physical ease","something that gives consolation"]}', '{"prefix":{"text":"com-","meaning":"with (一起)"},"root":{"text":"fort","meaning":"strong (強)"},"logic":"使人感到堅強安心，即「安慰」。"}', 'comfort zone / cold comfort; creature comfort / comfort zone / take comfort', '[{"en":"The hotel offers great comfort.","zh-TW":"這家飯店提供極佳的舒適度。"},{"en":"Step out of your comfort zone.","zh-TW":"走出你的舒適圈。"},{"en":"The hotel offers every comfort.","zh-TW":"飯店提供一切舒適設施。"},{"en":"She took comfort in her friend''s words.","zh-TW":"她從朋友的話語中得到安慰。"}]', '{"adjective":"comfortable","verb":"comfort","adverb":"comfortably"}', NULL, 3, 404),
(405, 'command', '/kəˈmænd/', 'noun', '{"zh-TW":["命令；指揮"],"en":["an order given","control or authority over something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mand","meaning":"order (命令)"},"logic":"向大家發出命令，即「指揮」。"}', 'give a command / chain of command / command of', '[{"en":"The officer gave the command to advance.","zh-TW":"軍官下達了前進的命令。"},{"en":"She has a good command of English.","zh-TW":"她的英語掌握得很好。"}]', '{"verb":"command","noun2":"commander"}', NULL, 3, 405),
(406, 'commence', '/kəˈmens/', 'verb', '{"zh-TW":["開始；著手"],"en":["to begin or start something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mence","meaning":"begin (開始)"},"logic":"一起開始，即「開始」。"}', 'commence operations/work/proceedings', '[{"en":"Construction will commence in early March.","zh-TW":"工程將於三月初開始。"},{"en":"The meeting commenced at 9 AM sharp.","zh-TW":"會議在上午9點整開始。"}]', '{"noun":"commencement"}', NULL, 3, 406),
(407, 'comment', '/ˈkɒment/', 'noun', '{"zh-TW":["評論；意見"],"en":["a verbal or written remark expressing an opinion"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"ment","meaning":"mind (心智)"},"logic":"完全出自心智的話，即「評論」。"}', 'make a comment / no comment / comment on', '[{"en":"The manager declined to comment on the rumors.","zh-TW":"經理拒絕對傳聞發表評論。"},{"en":"We welcome comments from our customers.","zh-TW":"我們歡迎客戶的意見。"}]', '{"noun":"commentary"}', NULL, 3, 407),
(408, 'commerce', '/ˈkɒmɜːrs/', 'noun', '{"zh-TW":["商業；貿易"],"en":["the activity of buying and selling on a large scale"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"merce","meaning":"trade (交易)"},"logic":"一起交易，即「商業」。"}', 'e-commerce / chamber of commerce / international commerce', '[{"en":"E-commerce has transformed the retail industry.","zh-TW":"電子商務已改變了零售產業。"},{"en":"International commerce drives economic growth.","zh-TW":"國際貿易推動經濟成長。"}]', '{"adjective":"commercial","verb":"commercialize"}', NULL, 3, 408),
(409, 'commission', '/kəˈmɪʃn/', 'noun', '{"zh-TW":["佣金；委員會"],"en":["a payment to an agent","a group appointed for a duty"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"miss","meaning":"send (送)"},"suffix":{"text":"-ion","meaning":"action (動作)"},"logic":"一起被派出的，即「委員會；佣金」。"}', 'sales commission / earn commission / commission a study', '[{"en":"Sales staff earn a 5% commission on each deal.","zh-TW":"銷售人員每筆交易可獲得5%佣金。"},{"en":"The commission will investigate the matter.","zh-TW":"委員會將調查此事。"}]', NULL, NULL, 4, 409),
(410, 'commit', '/kəˈmɪt/', 'verb', '{"zh-TW":["承諾；投入","犯（罪）","承諾；犯(罪)"],"en":["to pledge or dedicate oneself to","to carry out something illegal","to pledge or dedicate","to carry out a crime"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"mit","meaning":"send (送)"},"logic":"完全送出自己，即「承諾」。"}', 'commit to / commit resources / commit a crime; commit to / commit a crime / fully committed', '[{"en":"The company committed $1 million to the initiative.","zh-TW":"公司投入100萬美元於該計畫。"},{"en":"We are committed to delivering quality service.","zh-TW":"我們致力於提供優質服務。"},{"en":"She committed herself to finishing the project.","zh-TW":"她承諾完成這個專案。"},{"en":"He committed a serious offense.","zh-TW":"他犯了一項嚴重罪行。"}]', '{"noun":"commitment","adjective":"committed"}', NULL, 2, 410),
(411, 'commitment', '/kəˈmɪtmənt/', 'noun', '{"zh-TW":["承諾；投入"],"en":["a pledge or undertaking","dedication to a cause"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"mit","meaning":"send (送)"},"suffix":{"text":"-ment","meaning":"state (狀態)"},"logic":"完全送出自己的狀態，即「承諾」。"}', 'make a commitment / strong commitment / commitment to quality', '[{"en":"Our commitment to quality is unwavering.","zh-TW":"我們對品質的承諾堅定不移。"},{"en":"The project requires a significant time commitment.","zh-TW":"該專案需要投入大量時間。"}]', '{"verb":"commit","adjective":"committed"}', NULL, 4, 411),
(412, 'committee', '/kəˈmɪti/', 'noun', '{"zh-TW":["委員會"],"en":["a group of people appointed for a specific function"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mit","meaning":"send (送)"},"suffix":{"text":"-ee","meaning":"those who (…的人們)"},"logic":"一起被派出處理事務的人，即「委員會」。"}', 'steering committee / advisory committee / committee meeting', '[{"en":"The committee meets monthly to review progress.","zh-TW":"委員會每月開會檢視進度。"},{"en":"A new committee was formed to address the issue.","zh-TW":"成立了新委員會來處理此議題。"}]', NULL, NULL, 3, 412),
(413, 'commodity', '/kəˈmɒdəti/', 'noun', '{"zh-TW":["商品；大宗物資"],"en":["a raw material or agricultural product that can be bought and sold"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"mod","meaning":"measure/fit (衡量/適合)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"完全適合交易的物品，即「商品」。"}', 'commodity prices / commodity market / basic commodities', '[{"en":"Oil is one of the most traded commodities.","zh-TW":"石油是交易量最大的商品之一。"},{"en":"Commodity prices fluctuate based on supply and demand.","zh-TW":"商品價格根據供需波動。"}]', NULL, NULL, 3, 413),
(414, 'common', '/ˈkɒmən/', 'adjective', '{"zh-TW":["常見的；共同的"],"en":["happening often","shared by two or more","happening often; shared by all"]}', NULL, 'common ground / common sense; common sense / in common', '[{"en":"This is a common mistake.","zh-TW":"這是一個常見的錯誤。"},{"en":"We found common ground on the issue.","zh-TW":"我們在這個問題上找到了共識。"},{"en":"Colds are common in winter.","zh-TW":"感冒在冬天很常見。"},{"en":"We have a lot in common.","zh-TW":"我們有很多共同點。"}]', '{"adjective":"common","adverb":"commonly","noun":"commonality"}', NULL, 2, 414),
(415, 'communicate', '/kəˈmjuːnɪkeɪt/', 'verb', '{"zh-TW":["溝通；傳達"],"en":["to share or exchange information"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"munic","meaning":"share (分享)"},"suffix":{"text":"-ate","meaning":"to do (做)"},"logic":"一起分享，即「溝通」。"}', 'communicate effectively / communicate with', '[{"en":"It''s important to communicate clearly with clients.","zh-TW":"與客戶清楚溝通很重要。"},{"en":"The change was communicated to all employees.","zh-TW":"變更已傳達給所有員工。"}]', '{"noun":"communication"}', NULL, 4, 415),
(416, 'community', '/kəˈmjuːnəti/', 'noun', '{"zh-TW":["社區；社群"],"en":["a group of people living in the same area or sharing characteristics"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"mun","meaning":"service/duty (服務)"},"suffix":{"text":"-ity","meaning":"state (狀態)"},"logic":"一起服務的狀態，即「社區」。"}', 'local community / business community / online community', '[{"en":"The company supports the local community through donations.","zh-TW":"公司透過捐款支持當地社區。"},{"en":"The business community welcomed the new regulations.","zh-TW":"商業社群歡迎新法規。"}]', NULL, NULL, 3, 416),
(417, 'company', '/ˈkʌmpəni/', 'noun', '{"zh-TW":["公司；企業"],"en":["a commercial business organization"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pan","meaning":"bread (麵包)"},"suffix":{"text":"-y","meaning":"noun ending (名詞字尾)"},"logic":"一起吃麵包的人（夥伴），即「公司」。"}', 'company policy / parent company / run a company', '[{"en":"The company employs over 10,000 people worldwide.","zh-TW":"公司在全球僱用超過10,000人。"},{"en":"She started her own company at age 25.","zh-TW":"她25歲時創辦了自己的公司。"}]', NULL, NULL, 3, 417),
(418, 'compare', '/kəmˈpeər/', 'verb', '{"zh-TW":["比較；對照","比較"],"en":["to examine similarities and differences between","to examine the similarities and differences","to estimate similarities or differences"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"par","meaning":"equal (相等)"},"logic":"放在一起看是否相等，即「比較」。"}', 'compare with/to / compare prices; compare with / compare to; compare with / compare to / compared to', '[{"en":"Let''s compare the two proposals side by side.","zh-TW":"讓我們並排比較兩份提案。"},{"en":"Compared to last year, sales have increased 20%.","zh-TW":"與去年相比，銷售增長了20%。"},{"en":"Compare these two products.","zh-TW":"比較這兩個產品。"},{"en":"Compared to last year, sales rose.","zh-TW":"與去年相比，銷售額上升了。"},{"en":"Compare these two products before buying.","zh-TW":"購買前先比較這兩個產品。"},{"en":"Compared to last year, sales are up 20%.","zh-TW":"與去年相比，銷售增長了20%。"}]', '{"noun":"comparison","adjective":"comparable","adjective2":"comparative"}', NULL, 3, 418),
(419, 'compassion', '/kəmˈpæʃn/', 'noun', '{"zh-TW":["同情心；憐憫"],"en":["sympathy and concern for the sufferings of others"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pass","meaning":"suffer (受苦)"},"suffix":{"text":"-ion","meaning":"state (狀態)"},"logic":"一起感受痛苦，即「同情」。"}', 'show compassion / have compassion for', '[{"en":"She showed great compassion for the homeless.","zh-TW":"她對無家可歸的人表現出極大的同情。"},{"en":"A good leader leads with compassion.","zh-TW":"好的領導者以同理心領導。"}]', '{"adjective":"compassionate"}', NULL, 4, 419),
(420, 'compatible', '/kəmˈpætəbl/', 'adjective', '{"zh-TW":["相容的；兼容的","相容的"],"en":["able to exist or work together without conflict","able to work together without problems"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pat","meaning":"suffer/feel (感受)"},"suffix":{"text":"-ible","meaning":"able to (能夠)"},"logic":"能夠一起感受的，即「相容的」。"}', 'compatible with / compatible systems; compatible with / backward compatible', '[{"en":"The new software is compatible with all devices.","zh-TW":"新軟體與所有裝置相容。"},{"en":"Make sure the parts are compatible before ordering.","zh-TW":"訂購前請確認零件相容。"},{"en":"Is this software compatible with Mac?","zh-TW":"這軟體和Mac相容嗎？"},{"en":"The new version is backward compatible.","zh-TW":"新版本向下相容。"}]', '{"noun":"compatibility"}', NULL, 4, 420),
(421, 'compel', '/kəmˈpel/', 'verb', '{"zh-TW":["強迫；迫使"],"en":["to force or oblige someone to do something"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pel","meaning":"drive (驅使)"},"logic":"完全驅使，即「強迫」。"}', 'compel sb to do / feel compelled', '[{"en":"Economic pressures compelled the company to downsize.","zh-TW":"經濟壓力迫使公司裁員。"},{"en":"She felt compelled to report the safety violation.","zh-TW":"她覺得不得不舉報安全違規。"}]', '{"adjective":"compelling"}', NULL, 2, 421),
(422, 'compensate', '/ˈkɒmpenseɪt/', 'verb', '{"zh-TW":["補償；賠償"],"en":["to give something to make up for loss or damage"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pens","meaning":"weigh (稱重)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"完全衡量損失並補回，即「補償」。"}', 'compensate for / compensate employees', '[{"en":"The company compensated employees for overtime work.","zh-TW":"公司補償員工加班工作。"},{"en":"Nothing can compensate for the loss of reputation.","zh-TW":"沒有什麼能彌補名譽的損失。"},{"en":"The company compensated workers for overtime.","zh-TW":"公司補償了員工的加班費。"},{"en":"Nothing can compensate for the loss of a loved one.","zh-TW":"沒有什麼能彌補失去親人的痛苦。"}]', '{"noun":"compensation"}', NULL, 4, 422),
(423, 'compete', '/kəmˈpiːt/', 'verb', '{"zh-TW":["競爭","競爭；比賽"],"en":["to strive to gain something by defeating others","to try to win something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pete","meaning":"seek (尋求)"},"logic":"一起尋求同一目標，即「競爭」。"}', 'compete with/against / compete for; compete against / compete for', '[{"en":"Local firms must compete with international corporations.","zh-TW":"本地企業必須與國際公司競爭。"},{"en":"Ten candidates competed for the position.","zh-TW":"十位候選人競爭該職位。"},{"en":"Ten teams will compete in the tournament.","zh-TW":"十支隊伍將參加比賽。"},{"en":"Companies compete for customers.","zh-TW":"公司為爭取客戶而競爭。"}]', '{"noun":"competition","adjective":"competitive","noun2":"competitor"}', NULL, 3, 423),
(424, 'competent', '/ˈkɒmpɪtənt/', 'adjective', '{"zh-TW":["能勝任的；稱職的"],"en":["having the necessary ability or knowledge"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pet","meaning":"seek (尋求)"},"suffix":{"text":"-ent","meaning":"being (存在的)"},"logic":"完全具備所尋求的能力，即「稱職的」。"}', 'highly competent / competent in', '[{"en":"She is a highly competent project manager.","zh-TW":"她是一位非常稱職的專案經理。"},{"en":"The candidate must be competent in data analysis.","zh-TW":"候選人必須擅長數據分析。"}]', '{"noun":"competence"}', NULL, 3, 424),
(425, 'competitiveness', '/kəmˈpetɪtɪvnəs/', 'noun', '{"zh-TW":["競爭力"],"en":["the quality of being as good as or better than others"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pet","meaning":"seek (尋求)"},"suffix":{"text":"-iveness","meaning":"state (狀態)"},"logic":"一起尋求目標的能力狀態，即「競爭力」。"}', 'global competitiveness / enhance competitiveness / price competitiveness', '[{"en":"Innovation is key to maintaining competitiveness.","zh-TW":"創新是保持競爭力的關鍵。"},{"en":"Lower costs improve our price competitiveness.","zh-TW":"降低成本提升我們的價格競爭力。"}]', '{"adjective":"competitive","verb":"compete"}', NULL, 5, 425),
(426, 'compile', '/kəmˈpaɪl/', 'verb', '{"zh-TW":["彙編；匯集","編譯；彙編","編纂；彙整"],"en":["to collect and assemble information from various sources","to convert code into machine language","to produce by assembling information"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pile","meaning":"heap (堆積)"},"logic":"一起堆積，即「彙編」。"}', 'compile a report/list/database; compile code / compile a list; compile data / compile a list / compile a report', '[{"en":"The assistant compiled the data into a report.","zh-TW":"助理將數據彙編成報告。"},{"en":"We compiled a list of potential suppliers.","zh-TW":"我們匯集了一份潛在供應商清單。"},{"en":"The code failed to compile.","zh-TW":"程式碼編譯失敗了。"},{"en":"She compiled a list of errors.","zh-TW":"她彙整了一份錯誤清單。"},{"en":"She compiled a list of potential clients.","zh-TW":"她彙整了一份潛在客戶名單。"},{"en":"The report was compiled from various sources.","zh-TW":"報告是從各種來源彙整而成。"}]', '{"noun":"compilation","noun2":"compilation"}', NULL, 3, 426),
(427, 'complain', '/kəmˈpleɪn/', 'verb', '{"zh-TW":["抱怨；投訴"],"en":["to say you are unhappy about something"]}', NULL, 'complain about / complain to', '[{"en":"She complained about the noise.","zh-TW":"她抱怨噪音。"},{"en":"Customers complained to the manager.","zh-TW":"顧客向經理投訴。"}]', '{"noun":"complaint"}', NULL, 3, 427),
(428, 'complaint', '/kəmˈpleɪnt/', 'noun', '{"zh-TW":["投訴；抱怨"],"en":["an expression of dissatisfaction"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"plaint","meaning":"lament (悲嘆)"},"logic":"一起發出悲嘆，即「抱怨」。"}', 'file a complaint / customer complaint', '[{"en":"We received several complaints about the noise.","zh-TW":"我們收到了幾起關於噪音的投訴。"},{"en":"She filed a complaint with the manager.","zh-TW":"她向經理提出投訴。"}]', '{"verb":"complain","noun":"complainant"}', NULL, 3, 428),
(429, 'complement', '/ˈkɒmplɪment/', 'verb', '{"zh-TW":["補充；相輔相成"],"en":["to add to something to enhance or improve it"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"ple","meaning":"fill (填)"},"suffix":{"text":"-ment","meaning":"thing (事物)"},"logic":"完全填滿的東西，即「補充」。"}', 'complement each other / complement skills', '[{"en":"The two departments complement each other well.","zh-TW":"兩個部門相輔相成。"},{"en":"Her skills complement those of her business partner.","zh-TW":"她的技能與商業夥伴的互補。"}]', '{"adjective":"complementary"}', NULL, 4, 429),
(430, 'complete', '/kəmˈpliːt/', 'verb', '{"zh-TW":["完成；完整的"],"en":["to finish","having all parts"]}', NULL, 'complete a task / complete set', '[{"en":"Please complete the form by Friday.","zh-TW":"請在週五前填好表格。"},{"en":"The renovation is now complete.","zh-TW":"翻新工程已經完成了。"}]', '{"verb":"complete","adjective":"complete","noun":"completion","adverb":"completely"}', NULL, 3, 430),
(431, 'complex', '/ˈkɒmpleks/', 'adjective', '{"zh-TW":["複雜的"],"en":["consisting of many different parts; not easy to understand"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"plex","meaning":"weave (編織)"},"logic":"編織在一起的，即「複雜的」。"}', 'complex issue/system/process', '[{"en":"International tax law is extremely complex.","zh-TW":"國際稅法極其複雜。"},{"en":"The project involves complex logistics.","zh-TW":"該專案涉及複雜的物流。"}]', '{"noun":"complexity"}', NULL, 3, 431),
(432, 'compliance', '/kəmˈplaɪəns/', 'noun', '{"zh-TW":["合規；遵守"],"en":["the act of conforming to a rule or standard"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"pli","meaning":"fold/fill (折疊/充滿)"},"suffix":{"text":"-ance","meaning":"state (狀態)"},"logic":"完全充滿順從的狀態，即「合規」。"}', 'regulatory compliance / in compliance with / compliance officer', '[{"en":"The company is in full compliance with all regulations.","zh-TW":"公司完全遵守所有法規。"},{"en":"A compliance officer monitors adherence to policies.","zh-TW":"合規官監督政策遵守情況。"}]', '{"verb":"comply","adjective":"compliant"}', NULL, 4, 432),
(433, 'complicate', '/ˈkɒmplɪkeɪt/', 'verb', '{"zh-TW":["使複雜化"],"en":["to make something more difficult or complex"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"plic","meaning":"fold (折疊)"},"suffix":{"text":"-ate","meaning":"make (使)"},"logic":"使東西摺疊在一起，即「使複雜」。"}', 'complicate matters / further complicate', '[{"en":"His arrival only complicated matters.","zh-TW":"他的到來只是讓事情更複雜。"},{"en":"Don''t complicate things unnecessarily.","zh-TW":"不要把事情不必要地複雜化。"}]', '{"noun":"complication","adjective":"complicated"}', NULL, 4, 433),
(434, 'comply', '/kəmˈplaɪ/', 'verb', '{"zh-TW":["遵守；符合"],"en":["to act in accordance with a rule or request"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"ply","meaning":"fold/fill (折疊/充滿)"},"logic":"完全充滿順從，即「遵守」。"}', 'comply with regulations/standards/requirements', '[{"en":"All products must comply with safety standards.","zh-TW":"所有產品必須符合安全標準。"},{"en":"Failure to comply may result in penalties.","zh-TW":"不遵守可能導致罰款。"}]', '{"noun":"compliance","adjective":"compliant"}', NULL, 2, 434),
(435, 'component', '/kəmˈpəʊnənt/', 'noun', '{"zh-TW":["組件；成分"],"en":["a part or element of a larger whole"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pon","meaning":"put (放置)"},"suffix":{"text":"-ent","meaning":"thing (事物)"},"logic":"放置在一起的東西，即「組件」。"}', 'key component / component parts / electronic component', '[{"en":"Quality control is a key component of manufacturing.","zh-TW":"品質控制是製造業的關鍵組成部分。"},{"en":"The device contains over 500 electronic components.","zh-TW":"該裝置包含超過500個電子元件。"}]', NULL, NULL, 3, 435),
(436, 'compose', '/kəmˈpəʊz/', 'verb', '{"zh-TW":["組成；撰寫","作曲；組成"],"en":["to make up the whole","to write or create","to write music","to make up or form something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"pose","meaning":"put/place (放置)"},"logic":"一起放置，即「組成」。"}', 'be composed of / compose a letter; compose a symphony / compose oneself', '[{"en":"The committee is composed of 12 members.","zh-TW":"委員會由12名成員組成。"},{"en":"She composed a formal response to the complaint.","zh-TW":"她撰寫了對投訴的正式回覆。"},{"en":"Beethoven composed nine symphonies.","zh-TW":"貝多芬創作了九首交響曲。"}]', '{"noun":"composition","noun2":"composition"}', NULL, 3, 436),
(437, 'comprehensive', '/ˌkɒmprɪˈhensɪv/', 'adjective', '{"zh-TW":["全面的；綜合的"],"en":["including all or nearly all aspects of something"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"prehens","meaning":"grasp (抓住)"},"suffix":{"text":"-ive","meaning":"having quality (具有特質)"},"logic":"完全抓住所有面向的，即「全面的」。"}', 'comprehensive plan/review/report', '[{"en":"We conducted a comprehensive review of all policies.","zh-TW":"我們對所有政策進行了全面審查。"},{"en":"The package includes comprehensive health insurance.","zh-TW":"該方案包括全面的健康保險。"}]', '{"adverb":"comprehensively"}', NULL, 5, 437),
(438, 'comprise', '/kəmˈpraɪz/', 'verb', '{"zh-TW":["包含；由…組成"],"en":["to consist of; to be made up of"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"prise","meaning":"take (拿取)"},"logic":"一起拿取在內，即「包含」。"}', 'comprise of / be comprised of', '[{"en":"The team comprises specialists from various departments.","zh-TW":"團隊由各部門的專家組成。"},{"en":"Women comprise 45% of the workforce.","zh-TW":"女性占勞動力的45%。"}]', NULL, NULL, 3, 438),
(439, 'compromise', '/ˈkɒmprəmaɪz/', 'noun', '{"zh-TW":["妥協；折衷"],"en":["an agreement reached by each side giving up something"]}', '{"prefix":{"text":"com-","meaning":"together (一起)"},"root":{"text":"promise","meaning":"promise (承諾)"},"logic":"一起做出讓步承諾，即「妥協」。"}', 'reach a compromise / make a compromise', '[{"en":"Both sides reached a compromise on the pricing.","zh-TW":"雙方在定價上達成了妥協。"},{"en":"Quality should never be compromised for speed.","zh-TW":"不應為了速度而犧牲品質。"}]', NULL, NULL, 4, 439),
(440, 'compulsory', '/kəmˈpʌlsəri/', 'adjective', '{"zh-TW":["強制的；義務的","強制的；必修的"],"en":["required by law or rule; obligatory","required by law or rule"]}', '{"prefix":{"text":"com-","meaning":"together (完全)"},"root":{"text":"puls","meaning":"drive (驅使)"},"suffix":{"text":"-ory","meaning":"relating to (有關的)"},"logic":"完全被驅使的，即「強制的」。"}', 'compulsory training/education/insurance; compulsory education / compulsory subject', '[{"en":"Attendance at the safety training is compulsory.","zh-TW":"安全訓練的出席是強制性的。"},{"en":"The company has compulsory retirement at age 65.","zh-TW":"公司規定65歲強制退休。"},{"en":"Education is compulsory until age 16.","zh-TW":"教育在16歲前是義務的。"},{"en":"Math is a compulsory subject.","zh-TW":"數學是必修科目。"}]', '{"verb":"compel"}', NULL, 4, 440),
(441, 'computer', '/kəmˈpjuːtər/', 'noun', '{"zh-TW":["電腦"],"en":["an electronic device for processing data"]}', NULL, 'computer system / computer skills', '[{"en":"All employees need basic computer skills.","zh-TW":"所有員工都需要基本的電腦技能。"},{"en":"The computer system crashed this morning.","zh-TW":"電腦系統今早當機了。"}]', '{"noun":"computer","verb":"compute","noun2":"computation"}', NULL, 3, 441),
(442, 'conceal', '/kənˈsiːl/', 'verb', '{"zh-TW":["隱藏；隱瞞"],"en":["to keep from sight; to hide"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"ceal","meaning":"hide (藏)"},"logic":"完全藏起來，即「隱藏」。"}', 'conceal information/facts/identity', '[{"en":"The report accused the firm of concealing financial losses.","zh-TW":"報告指控該公司隱瞞財務虧損。"},{"en":"It is illegal to conceal material information from investors.","zh-TW":"向投資者隱瞞重要資訊是違法的。"}]', '{"noun":"concealment"}', NULL, 3, 442),
(443, 'concentrate', '/ˈkɒnsntreɪt/', 'verb', '{"zh-TW":["集中；專注"],"en":["to focus attention or effort on something","to focus all attention on something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"centr","meaning":"center (中心)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使聚集到中心，即「集中」。"}', 'concentrate on / concentrate efforts; concentrate on / unable to concentrate', '[{"en":"We should concentrate our efforts on core business.","zh-TW":"我們應該將精力集中在核心業務上。"},{"en":"The company decided to concentrate on the domestic market.","zh-TW":"公司決定專注於國內市場。"},{"en":"I need to concentrate on my work.","zh-TW":"我需要專注在工作上。"},{"en":"She couldn''t concentrate because of the noise.","zh-TW":"因為噪音她無法集中精神。"}]', '{"noun":"concentration"}', NULL, 4, 443),
(444, 'concept', '/ˈkɒnsept/', 'noun', '{"zh-TW":["概念；構想","概念"],"en":["an abstract idea or general notion"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"cept","meaning":"take/seize (抓取)"},"logic":"完全抓住的想法，即「概念」。"}', 'concept of / new concept / concept design; basic concept / new concept / concept of', '[{"en":"The concept of remote work has gained widespread acceptance.","zh-TW":"遠端工作的概念已獲得廣泛接受。"},{"en":"The team presented a new product concept.","zh-TW":"團隊展示了一個新的產品概念。"},{"en":"The concept is simple but effective.","zh-TW":"概念簡單但有效。"},{"en":"He introduced a new concept in design.","zh-TW":"他引入了一個新的設計概念。"}]', '{"adjective":"conceptual"}', NULL, 3, 444),
(445, 'concern', '/kənˈsɜːrn/', 'noun', '{"zh-TW":["關注；擔憂","事業","擔心；關切"],"en":["a matter of interest or importance","worry or anxiety","worry; something that causes anxiety"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"cern","meaning":"sift/separate (篩選)"},"logic":"完全篩選注意的事，即「關注」。"}', 'raise concerns / major concern / concern about; major concern / express concern / growing concern', '[{"en":"Safety is our primary concern.","zh-TW":"安全是我們首要關注的事項。"},{"en":"Several employees raised concerns about the policy.","zh-TW":"幾位員工對該政策提出了擔憂。"},{"en":"Safety is our primary concern.","zh-TW":"安全是我們最主要的關切。"},{"en":"There is growing concern about climate change.","zh-TW":"對氣候變遷的擔憂日益增加。"}]', '{"adjective":"concerned","verb":"concern","adjective2":"concerning"}', NULL, 3, 445),
(446, 'concert', '/ˈkɒnsərt/', 'noun', '{"zh-TW":["音樂會；演唱會"],"en":["a public musical performance"]}', NULL, 'concert hall / rock concert', '[{"en":"We went to a concert last night.","zh-TW":"我們昨晚去了演唱會。"},{"en":"The concert was sold out.","zh-TW":"演唱會門票售罄了。"}]', NULL, NULL, 3, 446),
(447, 'conclude', '/kənˈkluːd/', 'verb', '{"zh-TW":["結論；結束","總結；結束"],"en":["to bring to an end","to arrive at a judgment or opinion","to arrive at a judgment"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"clude","meaning":"close (關閉)"},"logic":"完全關閉，即「結束、下結論」。"}', 'conclude that / conclude a deal/meeting; conclude a meeting / conclude that', '[{"en":"The study concluded that the treatment was effective.","zh-TW":"研究得出結論認為該治療有效。"},{"en":"Negotiations were concluded successfully.","zh-TW":"談判成功結束。"},{"en":"The meeting concluded at 5 p.m.","zh-TW":"會議在下午五點結束。"},{"en":"The study concluded that exercise improves mental health.","zh-TW":"研究總結運動能改善心理健康。"}]', '{"noun":"conclusion","adjective":"conclusive"}', NULL, 3, 447),
(448, 'concrete', '/ˈkɒŋkriːt/', 'adjective', '{"zh-TW":["具體的；確切的"],"en":["existing in a material form; specific and definite"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"crete","meaning":"grow (生長)"},"logic":"一起生長凝固的，即「具體的」。"}', 'concrete evidence/plan/example', '[{"en":"Do you have any concrete evidence to support your claim?","zh-TW":"你有任何具體證據支持你的說法嗎？"},{"en":"We need a concrete plan, not just ideas.","zh-TW":"我們需要具體計畫，而不只是想法。"}]', NULL, NULL, 3, 448),
(449, 'condition', '/kənˈdɪʃn/', 'noun', '{"zh-TW":["條件；狀況"],"en":["the state of something","a stipulation or requirement"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"dit","meaning":"say (說)"},"suffix":{"text":"-ion","meaning":"action (動作)"},"logic":"完全說明的事，即「條件」。"}', 'working conditions / on condition that / terms and conditions', '[{"en":"The equipment is in excellent condition.","zh-TW":"設備狀況良好。"},{"en":"Please read the terms and conditions carefully.","zh-TW":"請仔細閱讀條款和條件。"}]', '{"adjective":"conditional"}', NULL, 3, 449);
INSERT INTO words (word_id, word, phonetic, part_of_speech, definitions_json, analysis_json, collocation, examples_json, word_family_json, secondary_meaning_note, difficulty, frequency_rank) VALUES
(450, 'conduct', '/kənˈdʌkt/', 'verb', '{"zh-TW":["進行；執行","行為"],"en":["to organize and carry out","the manner in which a person behaves"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"duct","meaning":"lead (引導)"},"logic":"一起引導進行，即「執行」。"}', 'conduct research/survey/business', '[{"en":"The firm conducted a thorough market analysis.","zh-TW":"公司進行了徹底的市場分析。"},{"en":"All employees must follow the code of conduct.","zh-TW":"所有員工必須遵守行為準則。"}]', NULL, NULL, 3, 450),
(451, 'conductor', '/kənˈdʌktər/', 'noun', '{"zh-TW":["指揮；導體"],"en":["a person who directs an orchestra","a substance that transmits heat or electricity"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"duct","meaning":"lead (引導)"},"suffix":{"text":"-or","meaning":"person who (…的人)"},"logic":"引導大家在一起的人，即「指揮」。"}', 'orchestra conductor / electrical conductor', '[{"en":"The conductor raised his baton.","zh-TW":"指揮舉起了指揮棒。"},{"en":"Copper is an excellent conductor of electricity.","zh-TW":"銅是優良的電導體。"}]', '{"verb":"conduct","noun":"conduction"}', NULL, 3, 451),
(452, 'confer', '/kənˈfɜːr/', 'verb', '{"zh-TW":["商議；授予"],"en":["to discuss something with someone","to grant or bestow"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"fer","meaning":"carry/bring (帶來)"},"logic":"一起帶來討論，即「商議」。"}', 'confer with / confer a degree/title', '[{"en":"I need to confer with my colleagues before deciding.","zh-TW":"我需要與同事商議後再決定。"},{"en":"The university conferred an honorary degree on her.","zh-TW":"大學授予她榮譽學位。"}]', '{"noun":"conference"}', NULL, 2, 452),
(453, 'confidence', '/ˈkɒnfɪdəns/', 'noun', '{"zh-TW":["信心；信任"],"en":["the feeling of being certain","trust in someone or something"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"fid","meaning":"trust (信任)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"完全信任的狀態，即「信心」。"}', 'consumer confidence / have confidence in / boost confidence', '[{"en":"Consumer confidence has risen for the third consecutive month.","zh-TW":"消費者信心連續第三個月上升。"},{"en":"I have full confidence in the team''s ability.","zh-TW":"我對團隊的能力充滿信心。"}]', '{"adjective":"confident","adverb":"confidently"}', NULL, 4, 453),
(454, 'confident', '/ˈkɒnfɪdənt/', 'adjective', '{"zh-TW":["有自信的"],"en":["feeling sure about one''s own abilities"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"fid","meaning":"trust (信任)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"完全信任自己的，即「有自信的」。"}', 'feel confident / confident speaker', '[{"en":"She is confident about passing the exam.","zh-TW":"她對通過考試很有信心。"},{"en":"He gave a confident presentation.","zh-TW":"他做了一場充滿自信的報告。"}]', '{"noun":"confidence","adverb":"confidently"}', NULL, 3, 454),
(455, 'confidential', '/ˌkɒnfɪˈdenʃl/', 'adjective', '{"zh-TW":["機密的；保密的"],"en":["intended to be kept secret"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"fid","meaning":"trust (信任)"},"suffix":{"text":"-ential","meaning":"relating to (有關的)"},"logic":"完全信任下才能知道的，即「機密的」。"}', 'confidential information / strictly confidential / confidential agreement', '[{"en":"This document contains confidential information.","zh-TW":"此文件包含機密資訊。"},{"en":"All client records are treated as strictly confidential.","zh-TW":"所有客戶記錄均被視為嚴格保密。"}]', '{"noun":"confidentiality"}', NULL, 4, 455),
(456, 'confine', '/kənˈfaɪn/', 'verb', '{"zh-TW":["限制；局限於"],"en":["to keep or restrict within certain limits"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"fine","meaning":"end/limit (邊界)"},"logic":"完全限制在邊界內，即「限制」。"}', 'confine to / be confined to', '[{"en":"The discussion should be confined to budget matters.","zh-TW":"討論應限制在預算事項。"},{"en":"The problem is not confined to one department.","zh-TW":"問題不僅限於一個部門。"}]', NULL, NULL, 3, 456),
(457, 'confirm', '/kənˈfɜːrm/', 'verb', '{"zh-TW":["確認；證實","確認"],"en":["to establish the truth or correctness of","to establish the truth of something"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"firm","meaning":"firm/strong (堅固)"},"logic":"使完全堅固確定，即「確認」。"}', 'confirm a booking/order/appointment; confirm a booking / confirm that / please confirm', '[{"en":"Please confirm your attendance by Friday.","zh-TW":"請在週五前確認您的出席。"},{"en":"The spokesperson confirmed the merger announcement.","zh-TW":"發言人確認了合併公告。"},{"en":"Please confirm your reservation by email.","zh-TW":"請透過電子郵件確認您的預訂。"},{"en":"The test results confirmed the diagnosis.","zh-TW":"檢驗結果確認了診斷。"}]', '{"noun":"confirmation"}', NULL, 3, 457),
(458, 'conflict', '/ˈkɒnflɪkt/', 'noun', '{"zh-TW":["衝突；矛盾"],"en":["a serious disagreement or argument","a serious disagreement","a prolonged struggle"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"flict","meaning":"strike (打擊)"},"logic":"一起打擊碰撞，即「衝突」。"}', 'conflict of interest / resolve a conflict; conflict of interest / armed conflict / resolve a conflict', '[{"en":"There is a conflict of interest in this situation.","zh-TW":"在這種情況下存在利益衝突。"},{"en":"The manager helped resolve the conflict between teams.","zh-TW":"經理幫助解決了團隊之間的衝突。"},{"en":"There is a conflict between the two departments.","zh-TW":"兩個部門之間有衝突。"},{"en":"The conflict lasted for several years.","zh-TW":"衝突持續了好幾年。"}]', '{"adjective":"conflicting","verb":"conflict"}', NULL, 3, 458),
(459, 'conform', '/kənˈfɔːrm/', 'verb', '{"zh-TW":["符合；遵從"],"en":["to comply with rules, standards, or conventions"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"form","meaning":"shape (形狀)"},"logic":"完全成為相同形狀，即「符合」。"}', 'conform to standards/regulations/expectations', '[{"en":"All products must conform to industry standards.","zh-TW":"所有產品必須符合行業標準。"},{"en":"The design conforms to local building regulations.","zh-TW":"設計符合當地建築法規。"}]', '{"noun":"conformity"}', NULL, 3, 459),
(460, 'confront', '/kənˈfrʌnt/', 'verb', '{"zh-TW":["面對；對抗"],"en":["to face a difficult situation or person"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"front","meaning":"face/forehead (面)"},"logic":"完全面對面，即「面對」。"}', 'confront a challenge/problem/issue', '[{"en":"Companies must confront the challenge of digital transformation.","zh-TW":"企業必須面對數位轉型的挑戰。"},{"en":"The CEO confronted the issue directly at the meeting.","zh-TW":"執行長在會議上直接面對了這個問題。"}]', '{"noun":"confrontation"}', NULL, 3, 460),
(461, 'conglomerate', '/kənˈɡlɒmərɪt/', 'noun', '{"zh-TW":["企業集團；綜合企業"],"en":["a large corporation made up of different businesses"]}', NULL, 'multinational conglomerate / media conglomerate', '[{"en":"The company grew into a multinational conglomerate.","zh-TW":"公司發展成為跨國企業集團。"},{"en":"The media conglomerate owns several TV stations.","zh-TW":"這家媒體集團擁有多個電視台。"}]', '{"noun":"conglomerate","noun2":"conglomeration"}', NULL, 4, 461),
(462, 'congress', '/ˈkɒŋɡrɛs/', 'noun', '{"zh-TW":["國會"],"en":["the national legislative body"]}', NULL, 'member of congress / congressional hearing', '[{"en":"Congress passed the new law.","zh-TW":"國會通過了新法律。"},{"en":"She was elected to Congress.","zh-TW":"她被選入了國會。"}]', '{"adjective":"congressional"}', NULL, 3, 462),
(463, 'connection', '/kəˈnɛkʃən/', 'noun', '{"zh-TW":["連接；關聯"],"en":["a link between things or people"]}', NULL, 'internet connection / personal connection', '[{"en":"I have a poor internet connection.","zh-TW":"我的網路連線很差。"},{"en":"There''s a connection between diet and health.","zh-TW":"飲食和健康之間有關聯。"}]', '{"verb":"connect","adjective":"connected"}', NULL, 4, 463),
(464, 'conscious', '/ˈkɒnʃəs/', 'adjective', '{"zh-TW":["有意識的；自覺的"],"en":["aware of and responding to surroundings","aware of and responding to one''s surroundings"]}', '{"prefix":{"text":"con-","meaning":"with (帶有)"},"root":{"text":"sci","meaning":"know (知道)"},"suffix":{"text":"-ous","meaning":"having (具有)"},"logic":"帶有知覺的，即「有意識的」。"}', 'conscious effort / self-conscious; conscious effort / conscious decision / self-conscious', '[{"en":"She made a conscious effort to be kind.","zh-TW":"她有意識地努力做到友善。"},{"en":"He was barely conscious after the accident.","zh-TW":"事故後他幾乎失去意識。"},{"en":"She made a conscious effort to be polite.","zh-TW":"她有意識地努力保持禮貌。"},{"en":"He was barely conscious after the accident.","zh-TW":"事故後他幾乎沒有意識了。"}]', '{"noun":"consciousness","adverb":"consciously"}', NULL, 3, 464),
(465, 'consecutive', '/kənˈsekjʊtɪv/', 'adjective', '{"zh-TW":["連續的"],"en":["following each other without interruption"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"secut","meaning":"follow (跟隨)"},"suffix":{"text":"-ive","meaning":"having quality (具有特質)"},"logic":"一起跟隨的，即「連續的」。"}', 'consecutive years/months/quarters', '[{"en":"Revenue has grown for five consecutive quarters.","zh-TW":"營收已連續五個季度成長。"},{"en":"She won the award for three consecutive years.","zh-TW":"她連續三年獲得該獎項。"}]', '{"adverb":"consecutively"}', NULL, 4, 465),
(466, 'consent', '/kənˈsent/', 'noun', '{"zh-TW":["同意；許可"],"en":["permission or agreement to do something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sent","meaning":"feel (感覺)"},"logic":"一起有相同感覺，即「同意」。"}', 'give consent / informed consent / without consent', '[{"en":"Written consent is required before processing personal data.","zh-TW":"處理個人資料前需要書面同意。"},{"en":"The change was made without employee consent.","zh-TW":"變更未經員工同意就進行了。"}]', NULL, NULL, 3, 466),
(467, 'consequence', '/ˈkɒnsɪkwəns/', 'noun', '{"zh-TW":["後果；結果"],"en":["a result or effect of an action or condition"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"sequ","meaning":"follow (跟隨)"},"suffix":{"text":"-ence","meaning":"state (狀態)"},"logic":"完全跟隨而來的，即「後果」。"}', 'as a consequence / face consequences / serious consequences', '[{"en":"As a consequence of the delay, costs increased significantly.","zh-TW":"由於延遲，成本大幅增加。"},{"en":"Failure to comply will have serious consequences.","zh-TW":"不遵守將會有嚴重後果。"}]', '{"adjective":"consequent","adverb":"consequently"}', NULL, 4, 467),
(468, 'conservation', '/ˌkɒnsərˈveɪʃn/', 'noun', '{"zh-TW":["保育；保存"],"en":["the protection of natural resources"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"serv","meaning":"keep (保存)"},"suffix":{"text":"-ation","meaning":"process (過程)"},"logic":"共同保存的過程，即「保育」。"}', 'wildlife conservation / energy conservation', '[{"en":"Wildlife conservation is critical for biodiversity.","zh-TW":"野生動物保育對生物多樣性至關重要。"},{"en":"Energy conservation reduces electricity bills.","zh-TW":"節約能源可以減少電費。"}]', '{"verb":"conserve","adjective":"conservative","noun2":"conservationist"}', NULL, 4, 468),
(469, 'conservative', '/kənˈsɜːrvətɪv/', 'adjective', '{"zh-TW":["保守的；謹慎的"],"en":["averse to change; cautious in estimate"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"serv","meaning":"keep (保持)"},"suffix":{"text":"-ative","meaning":"tending to (傾向)"},"logic":"傾向完全保持的，即「保守的」。"}', 'conservative estimate / conservative approach', '[{"en":"A conservative estimate puts the cost at $3 million.","zh-TW":"保守估計成本為300萬美元。"},{"en":"The company took a conservative approach to investing.","zh-TW":"公司採取保守的投資策略。"}]', NULL, NULL, 4, 469),
(470, 'consider', '/kənˈsɪdər/', 'verb', '{"zh-TW":["考慮；認為"],"en":["to think carefully about something"]}', NULL, 'consider doing / all things considered', '[{"en":"Please consider my proposal.","zh-TW":"請考慮我的提案。"},{"en":"She is considered an expert.","zh-TW":"她被認為是專家。"}]', '{"noun":"consideration","adjective":"considerable"}', NULL, 3, 470),
(471, 'considerable', '/kənˈsɪdərəbl/', 'adjective', '{"zh-TW":["相當大的；可觀的"],"en":["notably large in size, amount, or extent"]}', '{"prefix":{"text":"con-","meaning":"fully (完全)"},"root":{"text":"sider","meaning":"star (星)"},"suffix":{"text":"-able","meaning":"able to (能夠)"},"logic":"能夠完全被考量的（重要的），即「相當大的」。"}', 'considerable amount/effort/experience', '[{"en":"The project requires considerable investment.","zh-TW":"該專案需要大量投資。"},{"en":"She has considerable experience in marketing.","zh-TW":"她在行銷方面有豐富的經驗。"}]', '{"adverb":"considerably"}', NULL, 4, 471),
(472, 'considerate', '/kənˈsɪdərət/', 'adjective', '{"zh-TW":["體貼的；考慮周到的"],"en":["careful not to inconvenience or harm others"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sider","meaning":"star (星)"},"suffix":{"text":"-ate","meaning":"having (具有)"},"logic":"如同觀星般仔細考量他人，即「體貼的」。"}', 'considerate of others / thoughtful and considerate', '[{"en":"He is always considerate of other people''s feelings.","zh-TW":"他總是顧及他人的感受。"},{"en":"It was considerate of you to call first.","zh-TW":"你先打電話來很體貼。"}]', '{"noun":"consideration","verb":"consider"}', NULL, 4, 472),
(473, 'consist', '/kənˈsɪst/', 'verb', '{"zh-TW":["由…組成"],"en":["to be composed or made up of"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sist","meaning":"stand (站)"},"logic":"一起站立的，即「組成」。"}', 'consist of / consist in', '[{"en":"The team consists of 15 experienced professionals.","zh-TW":"團隊由15位經驗豐富的專業人士組成。"},{"en":"The test consists of three sections.","zh-TW":"測驗由三個部分組成。"}]', '{"adjective":"consistent","noun":"consistency"}', NULL, 3, 473),
(474, 'consistent', '/kənˈsɪstənt/', 'adjective', '{"zh-TW":["一致的；持續的"],"en":["unchanging over time; compatible"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sist","meaning":"stand (站立)"},"suffix":{"text":"-ent","meaning":"being (…的)"},"logic":"站在一起不變的，即「一致的」。"}', 'consistent results / consistent with / remain consistent', '[{"en":"She has been consistent in her performance.","zh-TW":"她的表現一直很穩定。"},{"en":"The data is consistent with our hypothesis.","zh-TW":"數據與我們的假設一致。"}]', '{"noun":"consistency","adverb":"consistently"}', NULL, 4, 474),
(475, 'consolidate', '/kənˈsɒlɪdeɪt/', 'verb', '{"zh-TW":["合併；鞏固"],"en":["to combine into a single more effective whole","to strengthen a position"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"solid","meaning":"solid (堅固)"},"suffix":{"text":"-ate","meaning":"to make (使)"},"logic":"使一起堅固，即「合併、鞏固」。"}', 'consolidate operations/position/power', '[{"en":"The company consolidated its three offices into one.","zh-TW":"公司將三個辦公室合併為一個。"},{"en":"We aim to consolidate our market position.","zh-TW":"我們旨在鞏固市場地位。"}]', '{"noun":"consolidation"}', NULL, 4, 475),
(476, 'consortium', '/kənˈsɔːrtiəm/', 'noun', '{"zh-TW":["聯盟；財團"],"en":["a group of companies working together"]}', NULL, 'form a consortium / industry consortium', '[{"en":"Three firms formed a consortium for the bid.","zh-TW":"三家公司組成聯盟參與競標。"},{"en":"The consortium invested in infrastructure.","zh-TW":"財團投資了基礎設施。"}]', '{"noun":"consortium","plural":"consortia"}', NULL, 4, 476),
(477, 'constant', '/ˈkɒnstənt/', 'adjective', '{"zh-TW":["不斷的；恆定的"],"en":["happening all the time without stopping"]}', NULL, 'constant pressure / constant speed', '[{"en":"The noise was constant.","zh-TW":"噪音持續不斷。"},{"en":"She''s under constant pressure.","zh-TW":"她承受著持續的壓力。"}]', '{"adverb":"constantly","noun":"constancy"}', NULL, 3, 477),
(478, 'constitute', '/ˈkɒnstɪtjuːt/', 'verb', '{"zh-TW":["構成；組成"],"en":["to be a part of a whole","to be equivalent to"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"stitut","meaning":"set up (建立)"},"logic":"一起建立起來的，即「構成」。"}', 'constitute a majority/threat/violation', '[{"en":"Foreign sales constitute 60% of total revenue.","zh-TW":"海外銷售構成總營收的60%。"},{"en":"This action may constitute a breach of contract.","zh-TW":"此行為可能構成違約。"}]', '{"noun":"constitution","adjective":"constitutional"}', NULL, 4, 478),
(479, 'constitution', '/ˌkɒnstɪˈtjuːʃən/', 'noun', '{"zh-TW":["憲法"],"en":["the fundamental laws of a country"]}', NULL, 'written constitution / constitutional right', '[{"en":"The constitution guarantees basic rights.","zh-TW":"憲法保障基本權利。"},{"en":"It''s protected by the constitution.","zh-TW":"這受到憲法保護。"}]', '{"adjective":"constitutional"}', NULL, 4, 479),
(480, 'constraint', '/kənˈstreɪnt/', 'noun', '{"zh-TW":["限制；約束"],"en":["a limitation or restriction"]}', '{"prefix":{"text":"con-","meaning":"together (完全)"},"root":{"text":"strain","meaning":"bind/tighten (綁/拉緊)"},"suffix":{"text":"-t","meaning":"noun ending"},"logic":"完全綁緊的，即「限制」。"}', 'budget constraints / time constraints / within constraints', '[{"en":"Budget constraints limit what we can accomplish.","zh-TW":"預算限制了我們能完成的事。"},{"en":"We must work within these constraints.","zh-TW":"我們必須在這些限制內工作。"}]', '{"verb":"constrain"}', NULL, 4, 480),
(481, 'construct', '/kənˈstrʌkt/', 'verb', '{"zh-TW":["建造；構建"],"en":["to build or erect something"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"struct","meaning":"build (建造)"},"logic":"一起建造，即「建造」。"}', 'construct a building/argument/plan', '[{"en":"The new headquarters will be constructed next year.","zh-TW":"新總部將於明年建造。"},{"en":"The lawyer constructed a compelling argument.","zh-TW":"律師構建了一個有說服力的論點。"}]', '{"noun":"construction","adjective":"constructive"}', NULL, 3, 481),
(482, 'construction', '/kənˈstrʌkʃən/', 'noun', '{"zh-TW":["建設；建造"],"en":["the process of building something"]}', NULL, 'under construction / construction site', '[{"en":"The building is under construction.","zh-TW":"大樓正在建設中。"},{"en":"Construction will be completed next year.","zh-TW":"建設將於明年完工。"}]', '{"verb":"construct","adjective":"constructive"}', NULL, 4, 482),
(483, 'consult', '/kənˈsʌlt/', 'verb', '{"zh-TW":["諮詢；查閱"],"en":["to seek information or advice from someone"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"sult","meaning":"take counsel (取得建議)"},"logic":"一起取得建議，即「諮詢」。"}', 'consult with / consult a specialist', '[{"en":"You should consult a lawyer before signing.","zh-TW":"簽名前你應該諮詢律師。"},{"en":"The management consulted with employees on the change.","zh-TW":"管理層就變革與員工進行了諮詢。"}]', '{"noun":"consultant","noun2":"consultation"}', NULL, 3, 483),
(484, 'consume', '/kənˈsjuːm/', 'verb', '{"zh-TW":["消費；消耗","消耗；消費"],"en":["to use up a resource","to eat or drink something","to use up; to eat or drink","to eat or drink"]}', '{"prefix":{"text":"con-","meaning":"completely (完全)"},"root":{"text":"sume","meaning":"take (拿取)"},"logic":"完全拿取用盡，即「消費」。"}', 'consume energy/resources/time; consume energy / consume food; consume energy / consume food / time-consuming', '[{"en":"The factory consumes large amounts of electricity.","zh-TW":"工廠消耗大量電力。"},{"en":"This process consumes too much time.","zh-TW":"這個流程消耗太多時間。"},{"en":"The factory consumes a lot of energy.","zh-TW":"工廠消耗大量能源。"},{"en":"Americans consume too much sugar.","zh-TW":"美國人攝取過多糖分。"},{"en":"Cars consume a lot of fuel.","zh-TW":"汽車消耗大量燃料。"},{"en":"Americans consume more sugar than recommended.","zh-TW":"美國人攝取的糖分超過建議量。"}]', '{"noun":"consumer","noun2":"consumption"}', NULL, 3, 484),
(485, 'contact', '/ˈkɒntækt/', 'noun', '{"zh-TW":["聯繫；接觸","聯絡人"],"en":["communication with someone","a person who may be consulted"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tact","meaning":"touch (觸碰)"},"logic":"一起觸碰，即「聯繫」。"}', 'contact information / make contact / point of contact', '[{"en":"Please don''t hesitate to contact us for more details.","zh-TW":"如需更多詳情，請隨時與我們聯繫。"},{"en":"She is our primary point of contact for the project.","zh-TW":"她是我們這個專案的主要聯絡人。"}]', NULL, NULL, 3, 485),
(486, 'contain', '/kənˈteɪn/', 'verb', '{"zh-TW":["包含；容納","控制"],"en":["to have within itself","to prevent from spreading","to have something inside"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tain","meaning":"hold (持有)"},"logic":"一起持有在內，即「包含」。"}', 'contain information / contain costs; contain information / self-contained', '[{"en":"The package contains fragile items.","zh-TW":"包裹內含易碎物品。"},{"en":"We must contain costs to maintain profitability.","zh-TW":"我們必須控制成本以維持獲利。"},{"en":"This box contains old photos.","zh-TW":"這個盒子裡有舊照片。"},{"en":"The drink contains no sugar.","zh-TW":"這飲料不含糖。"}]', '{"noun":"container","noun2":"content"}', NULL, 3, 486),
(487, 'contemporary', '/kənˈtempərəri/', 'adjective', '{"zh-TW":["當代的；同時期的"],"en":["living or occurring at the same time","modern or current","belonging to the present time"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tempor","meaning":"time (時間)"},"suffix":{"text":"-ary","meaning":"relating to (有關的)"},"logic":"在同一時間的，即「當代的」。"}', 'contemporary art/design/issues; contemporary art / contemporary music', '[{"en":"The office features contemporary design elements.","zh-TW":"辦公室採用當代設計元素。"},{"en":"We must address contemporary business challenges.","zh-TW":"我們必須面對當代商業挑戰。"},{"en":"The gallery specializes in contemporary art.","zh-TW":"這家畫廊專營當代藝術。"},{"en":"She is one of the greatest contemporary writers.","zh-TW":"她是最偉大的當代作家之一。"}]', '{"noun":"contemporary"}', NULL, 4, 487),
(488, 'content', '/ˈkɒntent/', 'noun', '{"zh-TW":["內容；目錄"],"en":["the material dealt with in a speech, text, or work"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tent","meaning":"hold (持有)"},"logic":"被一起持有在內的，即「內容」。"}', 'content marketing / table of contents / digital content', '[{"en":"The website needs fresh content updated weekly.","zh-TW":"網站需要每週更新新鮮內容。"},{"en":"Refer to the table of contents for guidance.","zh-TW":"請參閱目錄以獲取指導。"}]', NULL, NULL, 3, 488),
(489, 'contest', '/ˈkɒntest/', 'noun', '{"zh-TW":["比賽；競爭","質疑"],"en":["a competition","to dispute or challenge"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"test","meaning":"witness (見證)"},"logic":"一起見證對決，即「比賽」。"}', 'contest a claim / enter a contest', '[{"en":"The company decided to contest the lawsuit.","zh-TW":"公司決定對訴訟進行抗辯。"},{"en":"Employees can enter the innovation contest.","zh-TW":"員工可以參加創新比賽。"}]', '{"noun":"contestant"}', NULL, 3, 489),
(490, 'contestant', '/kənˈtɛstənt/', 'noun', '{"zh-TW":["參賽者"],"en":["a person who takes part in a competition"]}', NULL, 'reality show contestant / elimination of contestants', '[{"en":"The contestant answered correctly.","zh-TW":"參賽者答對了。"},{"en":"Fifty contestants entered the competition.","zh-TW":"五十位參賽者參加了比賽。"}]', '{"noun2":"contest"}', NULL, 4, 490),
(491, 'context', '/ˈkɒntekst/', 'noun', '{"zh-TW":["背景；上下文"],"en":["the circumstances that form the setting for an event"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"text","meaning":"weave (編織)"},"logic":"一起編織的環境，即「背景」。"}', 'in context / business context / cultural context', '[{"en":"The remarks must be understood in context.","zh-TW":"這些言論必須在上下文中理解。"},{"en":"In a business context, this term has a specific meaning.","zh-TW":"在商業背景下，這個術語有特定含義。"}]', '{"adjective":"contextual"}', NULL, 3, 491),
(492, 'contingency', '/kənˈtɪndʒənsi/', 'noun', '{"zh-TW":["應急措施；意外事件"],"en":["a future event that is possible but cannot be predicted","a possible future event that must be prepared for"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"ting","meaning":"touch (觸碰)"},"suffix":{"text":"-ency","meaning":"state (狀態)"},"logic":"可能觸碰到的事件狀態，即「意外事件」。"}', 'contingency plan / contingency fund', '[{"en":"We need a contingency plan in case of delays.","zh-TW":"我們需要一個應對延遲的應急計畫。"},{"en":"The budget includes a 10% contingency fund.","zh-TW":"預算包含10%的應急基金。"},{"en":"We need a contingency plan for supply disruptions.","zh-TW":"我們需要一個應對供應中斷的應急計畫。"},{"en":"Set aside a contingency fund.","zh-TW":"設置一筆應急基金。"}]', '{"adjective":"contingent","noun":"contingency"}', NULL, 4, 492),
(493, 'continue', '/kənˈtɪnjuː/', 'verb', '{"zh-TW":["繼續"],"en":["to keep going; not stop","to keep doing something without stopping"]}', NULL, 'continue to grow / continue with; continue to / continue with', '[{"en":"Sales continue to grow each quarter.","zh-TW":"銷售額每季持續成長。"},{"en":"Let''s continue with the presentation.","zh-TW":"讓我們繼續報告。"},{"en":"Please continue reading.","zh-TW":"請繼續閱讀。"},{"en":"The rain continued all day.","zh-TW":"雨下了一整天。"}]', '{"verb":"continue","adjective":"continuous","adverb":"continuously","noun":"continuation"}', NULL, 3, 493),
(494, 'contract', '/ˈkɒntrækt/', 'noun', '{"zh-TW":["合約；契約"],"en":["a written or spoken agreement that is legally binding"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tract","meaning":"draw (拉)"},"logic":"一起拉在一起的約定，即「合約」。"}', 'sign a contract / breach of contract / contract terms', '[{"en":"Both parties signed the contract last week.","zh-TW":"雙方上週簽署了合約。"},{"en":"The contract expires at the end of this year.","zh-TW":"合約於今年年底到期。"}]', '{"noun":"contractor","adjective":"contractual"}', NULL, 3, 494),
(495, 'contribute', '/kənˈtrɪbjuːt/', 'verb', '{"zh-TW":["貢獻；捐助"],"en":["to give something to help achieve a common goal"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"tribute","meaning":"give (給予)"},"logic":"一起給予，即「貢獻」。"}', 'contribute to / contribute funds/ideas', '[{"en":"Each team member contributed ideas to the project.","zh-TW":"每位團隊成員都為專案貢獻了想法。"},{"en":"Tourism contributes significantly to the local economy.","zh-TW":"旅遊業對當地經濟有重大貢獻。"}]', '{"noun":"contribution","noun2":"contributor"}', NULL, 4, 495),
(496, 'control', '/kənˈtroʊl/', 'noun', '{"zh-TW":["控制；管理"],"en":["the power to direct","to manage or regulate"]}', NULL, 'quality control / under control', '[{"en":"Quality control is essential in manufacturing.","zh-TW":"品質管理在製造業中至關重要。"},{"en":"The situation is under control.","zh-TW":"情況在掌控之中。"}]', '{"noun":"control","verb":"control","adjective":"controllable","noun2":"controller"}', NULL, 3, 496),
(497, 'controversial', '/ˌkɒntrəˈvɜːrʃl/', 'adjective', '{"zh-TW":["有爭議的"],"en":["causing disagreement or discussion"]}', '{"prefix":{"text":"contra-","meaning":"against (對立)"},"root":{"text":"vers","meaning":"turn (轉向)"},"suffix":{"text":"-ial","meaning":"relating to (有關的)"},"logic":"朝對立方向轉的，即「有爭議的」。"}', 'controversial decision/issue/topic', '[{"en":"The board made a controversial decision to outsource.","zh-TW":"董事會做出了有爭議的外包決定。"},{"en":"The policy remains highly controversial.","zh-TW":"該政策仍然極具爭議。"}]', '{"noun":"controversy"}', NULL, 5, 497),
(498, 'controversy', '/ˈkɒntrəvɜːrsi/', 'noun', '{"zh-TW":["爭議"],"en":["prolonged public disagreement"]}', '{"prefix":{"text":"contra-","meaning":"against (反對)"},"root":{"text":"vers","meaning":"turn (轉)"},"suffix":{"text":"-y","meaning":"state (狀態)"},"logic":"反向轉動的狀態，即「爭議」。"}', 'cause controversy / political controversy', '[{"en":"The decision caused a lot of controversy.","zh-TW":"這個決定引起了很多爭議。"},{"en":"The new law has been surrounded by controversy.","zh-TW":"新法律一直充滿爭議。"}]', '{"adjective":"controversial"}', NULL, 4, 498),
(499, 'convenient', '/kənˈviːniənt/', 'adjective', '{"zh-TW":["方便的；便利的"],"en":["fitting in well with needs or plans; easy to use"]}', '{"prefix":{"text":"con-","meaning":"together (一起)"},"root":{"text":"ven","meaning":"come (來)"},"suffix":{"text":"-ient","meaning":"being (存在的)"},"logic":"一起來到適合的地方，即「方便的」。"}', 'convenient location/time / at your convenience', '[{"en":"Please call us at your earliest convenience.","zh-TW":"請在您方便時盡早致電。"},{"en":"The office is in a convenient downtown location.","zh-TW":"辦公室位於便利的市中心位置。"}]', '{"noun":"convenience","adverb":"conveniently"}', NULL, 4, 499);